class HRManagementSystem:
    def __init__(self):
        self._employees = {}

    def add_employee(self, employee_id, name, position, department, salary):
        if employee_id in self._employees:
            return False
        self._employees[employee_id] = {
            'name': name,
            'position': position,
            'department': department,
            'salary': salary
        }
        return True

    def remove_employee(self, employee_id):
        if employee_id not in self._employees:
            return False
        del self._employees[employee_id]
        return True

    def update_employee(self, employee_id: int, employee_info: dict):
        employee = self.get_employee(employee_id)
        if employee is False:
            return False
        for key in employee_info:
            if key not in employee:
                return False
        for key, value in employee_info.items():
            employee[key] = value
        return True

    def get_employee(self, employee_id):
        if employee_id in self._employees:
            return self._employees[employee_id]
        return False

    def list_employees(self):
        return self._build_employee_listing()

    def _build_employee_listing(self):
        employee_data = {}
        for employee_id, employee_info in self._employees.items():
            employee_data[employee_id] = self._build_employee_details(employee_id, employee_info)
        return employee_data

    def _build_employee_details(self, employee_id, employee_info):
        employee_details = {'employee_ID': employee_id}
        employee_details.update(employee_info)
        return employee_details
